# api/api/commands/seed.py"""Flask CLI command to seed demo data for MyOwnClone testing."""import clickfrom datetime import timefrom sqlalchemy import selectfrom api.extensions import dbfrom api.models.myownclone import CloneConfig, MeetingType_, Availability# Demo data IDs (hardcoded as per task requirements)DEMO_TENANT_ID = "demo-tenant-001"DEMO_CLONE_ID = "demo-clone-001"@click.command("seed-demo-data")def seed_demo_data():    """Create demo data for testing MyOwnClone."""    click.echo("Seeding demo data...")    created = []    # ── Clone Config ──────────────────────────────────────────────────────────    existing_clone = db.session.execute(        select(CloneConfig).where(CloneConfig.slug == "demo-clone")    ).scalar_one_or_none()    if not existing_clone:        clone = CloneConfig(            id=DEMO_CLONE_ID,            tenant_id=DEMO_TENANT_ID,            name="Demo Clone",            slug="demo-clone",            description="A demo clone for testing",            avatar_url=None,            personality_tone="friendly",            language="en",            custom_domain=None,            active_modes=["teach", "support", "sales"],            is_active=True,        )        db.session.add(clone)        created.append("CloneConfig (demo-clone)")        click.echo("  ✓ Created CloneConfig: demo-clone")    else:        click.echo("  ✓ CloneConfig already exists: demo-clone")    # ── Meeting Type ─────────────────────────────────────────────────────────    existing_meeting = db.session.execute(        select(MeetingType_).where(            MeetingType_.clone_id == DEMO_CLONE_ID,            MeetingType_.name == "Consultation"        )    ).scalar_one_or_none()    if not existing_meeting:        meeting = MeetingType_(            clone_id=DEMO_CLONE_ID,            name="Consultation",            duration_minutes=30,            price_cents=9900,            description="Free initial consultation",            color="#6366f1",            active=True,        )        db.session.add(meeting)        created.append("MeetingType (Consultation)")        click.echo("  ✓ Created MeetingType: Consultation (30min, $99)")    else:        click.echo("  ✓ MeetingType already exists: Consultation")    # ── Availability Slot ────────────────────────────────────────────────────    existing_availability = db.session.execute(        select(Availability).where(            Availability.clone_id == DEMO_CLONE_ID,            Availability.day_of_week == 1,        )    ).scalar_one_or_none()    if not existing_availability:        availability = Availability(            clone_id=DEMO_CLONE_ID,            day_of_week=1,  # Monday            start_time=time(9, 0),            end_time=time(17, 0),            buffer_minutes=15,        )        db.session.add(availability)        created.append("Availability (Monday 09:00-17:00)")        click.echo("  ✓ Created Availability: Monday 09:00-17:00")    else:        click.echo("  ✓ Availability already exists for Monday")    # ── Admin User ───────────────────────────────────────────────────────────    # Note: User/Account management is handled by the base platform (models.account).    # For demo purposes, we create a stub record in the impersonation log if needed.    # The actual user creation would require the base platform's User model.    click.echo("")    click.echo("  ℹ Admin user (admin@youownclone.com / admin123)")    click.echo("     Note: User management is part of the base platform.")    db.session.commit()    click.echo("")    if created:        click.echo(f"Created: {', '.join(created)}")    else:        click.echo("No new records created (all data already exists)")    click.echo("Demo data seeding complete!")# Register command with Flask CLI# This is done via: app.cli.add_command(seed_demo_data)# See app_factory.py for registration